<template>
  <div class="workflow-page">
    <section class="page-head"><div><p class="eyebrow">PRODUCT WORKFLOW</p><h1>Vibecoding 工作台</h1><p class="subhead">把 PRD 变成可确认的流程原型，再用同一份流程完成上线前巡查。</p></div><div class="head-actions" style="display:flex;align-items:center;gap:12px;"><router-link to="/skill/vibecoding-pm-workflow"><a-button type="primary" ghost>进入 AI 智能工作流（推荐）</a-button></router-link><div class="head-meta"><span class="saved-dot"></span>{{ savedText }}</div></div></section>
    <div class="toolbar"><a-input v-model:value="projectName" class="project-input" placeholder="产品名称" /><a-segmented v-model:value="mode" :options="[{ label: '低保真原型', value: 'prototype' }, { label: '页面全流程巡查', value: 'audit' }]" /><a-button v-if="mode === 'audit'" @click="newRound">新建回归轮次</a-button></div>

    <section v-if="mode === 'prototype'" class="workspace-grid">
      <aside class="control-panel"><div class="panel-title"><span>01 / 输入需求</span><div style="display:flex;gap:6px;align-items:center;"><a-button type="link" size="small" @click="fillSamplePrd">填展示例</a-button><a-tag color="blue">草案提取</a-tag></div></div><a-textarea v-model:value="prd" :rows="13" placeholder="粘贴 PRD、页面清单或流程说明..." /><p class="hint">当前使用确定性关键词提取，结果必须人工确认后才能生成。</p><a-button type="primary" block :loading="analyzing" @click="analyze">分析流程草案</a-button><div class="quality-list"><span>覆盖首次使用、异常与恢复</span><span>不擅自补充未确认功能</span><span>单文件 HTML，可离线预览</span></div></aside>
      <main class="result-panel"><div class="panel-title"><span>02 / 确认页面与状态</span><a-tag>{{ confirmedCount }}/{{ flows.length }} 已确认</a-tag></div><a-empty v-if="!flows.length" description="输入 PRD 后生成流程草案" /><div v-else class="flow-list"> <div v-for="(item, index) in flows" :key="item.id" class="flow-row"><input v-model="item.confirmed" type="checkbox" class="flow-checkbox" :aria-label="`确认 ${item.pageName}`" /><div class="flow-index">{{ String(index + 1).padStart(2, '0') }}</div><div class="flow-content"><div class="flow-main"><a-input v-model:value="item.pageName" aria-label="页面名称" /><a-tag>{{ item.state }}</a-tag><a-tag v-if="item.changed" color="orange">已改动</a-tag></div><div class="flow-details"><span>操作：{{ item.action }}</span><span>→ {{ item.next }}</span></div><div class="flow-group">{{ item.group }}</div></div></div></div><div v-if="flows.length" class="result-actions"><a-button :disabled="!allConfirmed" type="primary" @click="generate">生成低保真原型</a-button><span v-if="!allConfirmed">请确认全部 {{ flows.length }} 个流程项</span><a-button v-if="prototypeHtml" @click="downloadPrototype">下载 HTML</a-button></div></main>
    </section>

    <section v-else class="audit-layout"><aside class="audit-sidebar"><div class="panel-title"><span>巡查轮次 {{ round }}</span><a-tag :color="auditProgress === 100 ? 'green' : 'blue'">{{ auditProgress }}%</a-tag></div><a-textarea v-model:value="prd" :rows="6" placeholder="输入或粘贴流程说明，用于生成走查清单" /><a-button type="primary" block @click="generateAudit">生成走查清单</a-button><div class="audit-stats"><strong>{{ auditItems.length }}</strong><span>个页面状态</span></div><div class="legend"><span><i class="pass"></i>可以 {{ counts.pass }}</span><span><i class="todo"></i>待改 {{ counts.todo }}</span><span><i class="blocked"></i>阻塞 {{ counts.blocked }}</span></div></aside><main class="audit-content"><a-empty v-if="!auditItems.length" description="生成走查清单后开始逐屏验收" /><template v-else><div v-for="group in auditGroups" :key="group" class="audit-group"><h2>{{ group }}</h2><article v-for="item in auditItems.filter((entry) => entry.group === group)" :key="item.id" class="audit-card" :class="{ changed: item.changed }"><header><div><span class="item-kicker">{{ item.changed ? '回归验证 · 已改动' : '页面状态' }}</span><h3>{{ item.pageName }}</h3></div><a-tag :color="item.status === 'blocked' ? 'red' : item.status === 'todo' ? 'orange' : item.status === 'pass' ? 'green' : 'default'">{{ statusLabel(item.status) }}</a-tag></header><div class="audit-info"><p><b>状态：</b>{{ item.state }}</p><p><b>复现：</b>{{ item.reproduce }}</p><p><b>预期：</b>{{ item.expected }}</p></div><a-textarea v-model:value="item.feedback" :rows="3" placeholder="记录实际结果、问题证据或验收意见" @input="touchSaved" /><div v-if="item.previousFeedback" class="previous">上一轮反馈：{{ item.previousFeedback }}</div><footer><div class="quick-actions"><a-button size="small" :type="item.status === 'pass' ? 'primary' : 'default'" @click="setAuditStatus(item, 'pass')">可以</a-button><a-button size="small" :type="item.status === 'todo' ? 'primary' : 'default'" @click="setAuditStatus(item, 'todo')">待改</a-button><a-button size="small" danger :type="item.status === 'blocked' ? 'primary' : 'default'" @click="setAuditStatus(item, 'blocked')">阻塞</a-button></div><a-input v-model:value="item.actual" aria-label="实际结果" placeholder="实际结果摘要" @input="touchSaved" /></footer></article></div><div class="export-bar"><a-button @click="downloadMarkdown">导出 Markdown</a-button><a-button @click="downloadJson">导出 JSON</a-button></div></template></main></section>
    <div v-if="prototypeHtml" class="preview-section"><div class="panel-title"><span>03 / 原型预览</span><a-button size="small" @click="downloadPrototype">下载 HTML</a-button></div><iframe title="低保真原型预览" :src="prototypeUrl"></iframe></div>
  </div>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { message } from 'ant-design-vue'
import { analyzePrd, buildPrototypeHtml, exportAuditMarkdown, loadWorkflowState, redactSecrets, saveWorkflowState, statusLabel, toAuditItems, type AuditItem, type AuditStatus, type FlowItem, type WorkflowMode } from '@/services/vibecodingWorkflow'

const SAMPLE_PRD = `【项目】AI 图文内容发布平台
【核心目标】帮助创作者一键将长文拆解为社交图文，并完成多渠道发布与审批。
【核心角色】创作者、内容审核员

【主流程】
1. 账号登录：用户输入账号密码登录系统，支持首次登录修改初始密码。
2. 创作首页：展示最近草稿、历史生成记录和数据卡片；支持从模板新建。
3. 创建图文内容：粘贴长文内容或 PRD，选择目标排版模板与风格。
4. 预览与确认：展示拆解后的多卡片线框图，用户可微调文案与布局，进行人工确认。
5. 提交发布：发起合规检查与接口发布，发布成功后提示成功并展示分享链接。

【异常与边界流程】
- 首次使用：新用户引导遮罩，提示阅读新手教程。
- 权限申请：创作者发布需开启对象存储与外部发布授权，未授权时进入授权引导页。
- 加载与超时：长文本解析过程展示进度条与取消按钮；请求超时提供重试机制。
- 空数据状态：草稿箱或历史列表为空时展示 Empty 引导卡片。
- 失败与重试：若接口限流或违规拦截，明确展示失败原因，并保留已输入内容支持一键重试。`

function fillSamplePrd() {
  prd.value = SAMPLE_PRD
  projectName.value = 'AI 图文内容发布平台'
  message.success('已填入标准示例 PRD 数据')
}

const mode = ref<WorkflowMode>('prototype'), projectName = ref('我的产品'), prd = ref('登录\n首页\n创建内容\n提交成功\n加载中\n无数据\n失败后重试'), flows = ref<FlowItem[]>([]), auditItems = ref<AuditItem[]>([]), round = ref(1), prototypeHtml = ref(''), savedText = ref('未保存'), analyzing = ref(false)
let saveTimer: ReturnType<typeof setTimeout> | undefined
const confirmedCount = computed(() => flows.value.filter((item) => item.confirmed).length)
const allConfirmed = computed(() => flows.value.length > 0 && confirmedCount.value === flows.value.length)
const prototypeUrl = computed(() => prototypeHtml.value ? `data:text/html;charset=utf-8,${encodeURIComponent(prototypeHtml.value)}` : '')
const auditGroups = computed(() => [...new Set(auditItems.value.map((item) => item.group))])
const counts = computed(() => ({ pass: auditItems.value.filter((item) => item.status === 'pass').length, todo: auditItems.value.filter((item) => item.status === 'todo').length, blocked: auditItems.value.filter((item) => item.status === 'blocked').length }))
const auditProgress = computed(() => auditItems.value.length ? Math.round(auditItems.value.filter((item) => item.status !== 'unreviewed').length / auditItems.value.length * 100) : 0)
const touchSaved = () => { savedText.value = '已修改，保存中'; clearTimeout(saveTimer); saveTimer = setTimeout(persist, 300) }
const persist = () => { saveWorkflowState({ mode: mode.value, projectName: projectName.value, prd: prd.value, flows: flows.value, auditItems: auditItems.value, round: round.value }); savedText.value = `已保存 ${new Date().toLocaleTimeString()}` }
watch([mode, projectName, prd, flows, auditItems, round], touchSaved, { deep: true })
function analyze() { analyzing.value = true; window.setTimeout(() => { flows.value = analyzePrd(prd.value); prototypeHtml.value = ''; analyzing.value = false; message.success('流程草案已生成，请逐项确认') }, 160) }
function generate() { prototypeHtml.value = buildPrototypeHtml(projectName.value, flows.value); flows.value.forEach((item) => { item.changed = false }); message.success('低保真原型已生成') }
function generateAudit() { const next = toAuditItems(flows.value.length ? flows.value : analyzePrd(prd.value)); const old = new Map(auditItems.value.map((item) => [item.id, item])); auditItems.value = next.map((item) => { const previous = old.get(item.id); return previous ? { ...item, feedback: previous.feedback, actual: previous.actual, status: 'unreviewed', previousFeedback: previous.feedback || undefined, changed: previous.status !== 'unreviewed' } : item }); message.success('走查清单已生成') }
function newRound() { round.value += 1; auditItems.value = auditItems.value.map((item) => ({ ...item, previousFeedback: item.feedback || item.previousFeedback, changed: true, status: 'unreviewed', feedback: '', actual: '' })); message.info(`已创建第 ${round.value} 轮回归验证`) }
function setAuditStatus(item: AuditItem, status: AuditStatus) { item.status = status; touchSaved() }
function download(name: string, content: string, type: string) { const url = URL.createObjectURL(new Blob([content], { type })); const link = document.createElement('a'); link.href = url; link.download = name; link.click(); URL.revokeObjectURL(url) }
function downloadPrototype() { download(`${projectName.value || 'prototype'}.html`, prototypeHtml.value, 'text/html;charset=utf-8') }
function downloadMarkdown() { download(`${projectName.value || 'audit'}-round-${round.value}.md`, exportAuditMarkdown(projectName.value, round.value, auditItems.value), 'text/markdown;charset=utf-8') }
function downloadJson() { download(`${projectName.value || 'audit'}-round-${round.value}.json`, redactSecrets(JSON.stringify({ projectName: projectName.value, round: round.value, items: auditItems.value }, null, 2)), 'application/json;charset=utf-8') }
onMounted(() => { const state = loadWorkflowState<{ mode: WorkflowMode; projectName: string; prd: string; flows: FlowItem[]; auditItems: AuditItem[]; round: number }>(); if (state) { mode.value = state.mode || 'prototype'; projectName.value = state.projectName || projectName.value; prd.value = state.prd || prd.value; flows.value = state.flows || []; auditItems.value = state.auditItems || []; round.value = state.round || 1 } })
onBeforeUnmount(() => clearTimeout(saveTimer))
</script>

<style scoped>
.workflow-page{max-width:1440px;margin:auto;padding:48px 32px 72px;color:var(--color-text)}.page-head{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;margin-bottom:28px}.eyebrow,.item-kicker{margin:0 0 8px;color:var(--color-primary-dark);font:600 11px/1.2 'JetBrains Mono',monospace;letter-spacing:1px}.page-head h1{margin:0;font-size:32px;letter-spacing:0}.subhead{margin:10px 0 0;color:var(--color-text-secondary);font-size:15px}.head-meta{font-size:12px;color:var(--color-text-secondary);white-space:nowrap}.saved-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#52c41a;margin-right:7px}.toolbar{display:flex;align-items:center;gap:12px;padding:14px 0;border-top:1px solid var(--color-border);border-bottom:1px solid var(--color-border);margin-bottom:20px}.project-input{max-width:240px}.workspace-grid,.audit-layout{display:grid;grid-template-columns:320px minmax(0,1fr);gap:20px;align-items:start}.control-panel,.result-panel,.audit-sidebar,.audit-content,.preview-section{background:var(--surface-panel);border:1px solid var(--color-border);padding:22px}.panel-title{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;font-size:13px;font-weight:700}.hint{font-size:12px;line-height:1.5;color:var(--color-text-secondary)}.quality-list{display:grid;gap:9px;margin-top:20px;color:var(--color-text-secondary);font-size:12px}.quality-list span:before{content:'✓';color:var(--color-primary);margin-right:8px}.flow-list{display:grid;gap:10px}.flow-row{display:grid;grid-template-columns:24px 30px minmax(0,1fr);gap:10px;align-items:start;padding:13px 0;border-bottom:1px solid var(--color-border)}.flow-index{font:12px 'JetBrains Mono',monospace;color:var(--color-text-secondary);padding-top:5px}.flow-main{display:flex;align-items:center;gap:8px}.flow-main .ant-input{max-width:340px}.flow-details{display:flex;flex-wrap:wrap;gap:8px;margin-top:9px;color:var(--color-text-secondary);font-size:12px}.flow-group{margin-top:8px;font-size:11px;color:var(--color-primary-dark)}.result-actions,.export-bar{display:flex;align-items:center;gap:12px;padding-top:20px}.result-actions span{font-size:12px;color:var(--color-text-secondary)}.preview-section{margin-top:20px}.preview-section iframe{display:block;width:100%;height:620px;border:1px solid #d1d5db;background:#f3f4f6}.audit-stats{display:flex;align-items:baseline;gap:8px;margin:26px 0 18px;border-top:1px solid var(--color-border);padding-top:20px}.audit-stats strong{font-size:32px}.audit-stats span,.legend{font-size:12px;color:var(--color-text-secondary)}.legend{display:grid;gap:10px}.legend i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:7px}.pass{background:#52c41a}.todo{background:#faad14}.blocked{background:#ff4d4f}.audit-group{margin-bottom:28px}.audit-group h2{font-size:18px;margin:0 0 12px}.audit-card{background:var(--surface-panel);border:1px solid var(--color-border);padding:18px;margin-bottom:10px}.audit-card.changed{border-left:3px solid #faad14}.audit-card header,.audit-card footer{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.audit-card h3{margin:0;font-size:16px}.audit-info{margin:16px 0;color:var(--color-text-secondary);font-size:13px;line-height:1.55}.audit-info p{margin:5px 0}.audit-info b{color:var(--color-text)}.previous{margin-top:10px;padding:9px 12px;background:var(--color-background-secondary);color:var(--color-text-secondary);font-size:12px}.audit-card footer{align-items:center;margin-top:12px}.audit-card footer .ant-input{max-width:280px}.quick-actions{display:flex;gap:8px}@media(max-width:900px){.workflow-page{padding:28px 16px 48px}.page-head{align-items:flex-start;flex-direction:column}.workspace-grid,.audit-layout{grid-template-columns:1fr}.control-panel,.audit-sidebar{position:static}.toolbar{flex-wrap:wrap}.project-input{max-width:none;flex:1;min-width:180px}}@media(max-width:560px){.page-head h1{font-size:26px}.toolbar .ant-segmented{width:100%}.toolbar .ant-segmented :deep(.ant-segmented-item-label){padding-inline:6px;font-size:12px}.result-actions,.export-bar,.audit-card footer{align-items:stretch;flex-direction:column}.flow-main{align-items:flex-start;flex-direction:column}.flow-main .ant-input{max-width:none;width:100%}.audit-card footer .ant-input{max-width:none}.preview-section iframe{height:480px}}
a-checkbox[aria-label^="确认 "]{display:block;width:18px;height:18px;cursor:pointer}
</style>
